def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    dangerous_prev = []
    weak_count = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                weak_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 0) > 3 and opp.get('budget', 0) > DAILY_SALARY * 2:
                    dangerous_prev.append(float(bid))

    if not alive:
        return float(min(budget, 20.0))

    slots = max(1, int(supply // WATER_REQ))
    high_supply = slots >= 2

    highest_prev = max(prev_bids) if prev_bids else 0.0
    pressure_prev = max(dangerous_prev) if dangerous_prev else highest_prev

    urgency = 0
    if hp <= 3:
        urgency += 2
    elif hp <= 5:
        urgency += 1
    if no_water >= 2:
        urgency += 2
    elif no_water >= 1:
        urgency += 1

    if urgency >= 3:
        base = max(92.0, pressure_prev + 3.0)
    elif urgency >= 2:
        base = max(78.0, pressure_prev + 2.0)
    else:
        if high_supply:
            base = 46.0 if weak_count >= 1 else 58.0
            if pressure_prev > 0:
                base = max(base, min(86.0, pressure_prev * 0.78))
        else:
            base = max(66.0, pressure_prev + 1.5 if pressure_prev > 0 else 72.0)

    if highest_prev >= 120 and urgency == 0 and hp >= 6 and no_water == 0:
        base = min(base, 52.0 if high_supply else 60.0)

    if day >= 8:
        base += 6.0
    if day == 10:
        base += 8.0

    reserve_floor = 0.0
    if day < 10:
        reserve_floor = max(0.0, (10 - day) * 8.0)
    affordable = max(0.0, budget - reserve_floor)
    if affordable <= 0:
        affordable = min(budget, DAILY_SALARY * 0.6)

    bid = min(base, budget, max(1.0, affordable))

    if urgency >= 3:
        bid = min(budget, max(bid, 95.0))
    elif urgency >= 2:
        bid = min(budget, max(bid, 82.0))

    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    EPISODE_DAYS = 10 

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_budget, DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.8

    if my_hp <= 2:
        base_bid = DAILY_SALARY * 1.2 
    elif my_hp <= 5:
        base_bid = DAILY_SALARY * 1.0
    else:
        base_bid = DAILY_SALARY * 0.8

    num_full_water_slots = int(current_supply // WATER_REQ)

    if num_full_water_slots < (num_alive_opponents + 1):
        if my_hp <= 2:
            base_bid = max(base_bid, DAILY_SALARY * 1.3)
        else:
            base_bid = max(base_bid, DAILY_SALARY * 1.1)

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.9:
            base_bid = max(base_bid, highest_prev_bid + 5.0)
        elif highest_prev_bid >= DAILY_SALARY * 0.7:
            base_bid = max(base_bid, highest_prev_bid + 2.0)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2:
        if my_hp <= 5:
            base_bid = max(base_bid, DAILY_SALARY * 1.25)
        else:
            base_bid = max(base_bid, DAILY_SALARY * 1.1)

    final_bid = max(1.0, base_bid)

    return min(my_budget, final_bid)

