def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = {aid: o for aid, o in opponents_status.items() if o['alive']}

    # gather yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents.values():
        trace = opp.get('previous_trace')
        if trace and trace.get('bid') is not None:
            yesterday_bids.append(trace['bid'])

    # Determine base bid
    if hp <= 2:
        # desperate: need water at any reasonable cost
        base_bid = min(budget, DAILY_SALARY * 0.9)
    elif hp <= 4:
        # moderate need
        if yesterday_bids:
            highest = max(yesterday_bids)
            base_bid = min(budget, max(DAILY_SALARY * 0.5, highest + 1.5))
        else:
            base_bid = min(budget, DAILY_SALARY * 0.6)
    else:
        # healthy, can be conservative
        if yesterday_bids:
            highest = max(yesterday_bids)
            # outbid the highest yesterday but not more than 70% salary
            base_bid = min(budget, max(DAILY_SALARY * 0.4, highest + 1.0))
        else:
            base_bid = min(budget, DAILY_SALARY * 0.4)

    # ensure minimum bid if budget allows, to not die of thirst
    if no_water_days >= 1 and budget > 0:
        # last two days: bid more aggressively
        if day >= 8:
            base_bid = max(base_bid, min(budget, DAILY_SALARY * 0.85))

    # clamp to budget
    return min(budget, base_bid)
